<div class="page-head"><div><a href="/app/interventi" class="text-decoration-none">← Torna agli interventi</a><p class="text-uppercase small fw-semibold text-success mt-3 mb-1">Intervento #<?= (int)$intervento['id'] ?></p><h1 class="h2 mb-2"><?= e($intervento['cliente']) ?> · <?= e($intervento['sede_nome']) ?></h1><div class="d-flex flex-wrap gap-2"><span class="badge rounded-pill text-bg-primary"><?= e(lbl($stati['intervento_stato'],$intervento['stato'])) ?></span><span class="badge rounded-pill text-bg-light"><?= e(lbl($stati['servizio_tipo'],$intervento['tipo_servizio'])) ?></span></div></div><div class="actions"><?php if($auth->can('interventi','modifica')): ?><a class="btn btn-outline-primary" href="/app/interventi/<?= (int)$intervento['id'] ?>/modifica">Modifica intervento</a><?php endif ?><?php if($auth->can('interventi','eliminazione')): ?><form method="post" action="/app/interventi/<?= (int)$intervento['id'] ?>/archivia" class="m-0"><?= $csrf->field() ?><button class="btn btn-outline-danger" data-confirm="Archiviare questo intervento? L’attività non comparirà più negli elenchi attivi.">Archivia</button></form><?php endif ?></div></div>
<div class="row g-4"><div class="col-lg-7"><section class="card border-0 shadow-sm mb-4"><div class="card-body p-4"><h2 class="h5">Dettagli del lavoro</h2><dl class="row mt-3 mb-0"><dt class="col-sm-4 text-secondary">Sede</dt><dd class="col-sm-8"><?= e(trim(($intervento['sede_indirizzo']??'').' '.($intervento['sede_citta']??''))?:'Indirizzo non indicato') ?></dd><dt class="col-sm-4 text-secondary">Referente sul posto</dt><dd class="col-sm-8"><?= e($intervento['referente_nome']?:'Non indicato') ?><?= $intervento['referente_telefono']?' · '.e($intervento['referente_telefono']):'' ?></dd><dt class="col-sm-4 text-secondary">Orari di accesso</dt><dd class="col-sm-8"><?= e($intervento['orari_consentiti']?:'Non indicati') ?></dd><dt class="col-sm-4 text-secondary">Istruzioni accesso</dt><dd class="col-sm-8"><?= nl2br(e($intervento['istruzioni_accesso']??'—')) ?></dd><dt class="col-sm-4 text-secondary">Infestante</dt><dd class="col-sm-8"><?= e($intervento['infestante']?:'Non specificato') ?></dd><dt class="col-sm-4 text-secondary">Pianificazione</dt><dd class="col-sm-8"><?= e(fmt_data($intervento['pianificato_il'])) ?><?= $intervento['durata_stimata_min']?' · circa '.(int)$intervento['durata_stimata_min'].' minuti':'' ?></dd><dt class="col-sm-4 text-secondary">Operatori</dt><dd class="col-sm-8"><?= $operatori?e(implode(', ',array_map(fn($o)=>$o['nome'].' '.$o['cognome'],$operatori))):'Non assegnati' ?></dd><dt class="col-sm-4 text-secondary">Descrizione</dt><dd class="col-sm-8"><?= nl2br(e($intervento['descrizione']?:'—')) ?></dd><dt class="col-sm-4 text-secondary">Istruzioni operative</dt><dd class="col-sm-8"><?= nl2br(e($intervento['istruzioni']?:'—')) ?></dd></dl></div></section>
<section class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="h5">Rapporto dell’intervento</h2><dl class="row mt-3"><dt class="col-sm-4 text-secondary">Inizio effettivo</dt><dd class="col-sm-8"><?= e(fmt_data($intervento['inizio_effettivo'])) ?></dd><dt class="col-sm-4 text-secondary">Fine effettiva</dt><dd class="col-sm-8"><?= e(fmt_data($intervento['fine_effettiva'])) ?></dd><dt class="col-sm-4 text-secondary">Esito</dt><dd class="col-sm-8"><?= nl2br(e($intervento['esito']?:'Non ancora compilato')) ?></dd><dt class="col-sm-4 text-secondary">Note e anomalie</dt><dd class="col-sm-8"><?= nl2br(e($intervento['note_operatore']?:'—')) ?></dd></dl>
<?php if($puoEseguire): ?><hr><h3 class="h6">Aggiorna rapporto</h3><form method="post" action="/app/interventi/<?= (int)$intervento['id'] ?>/esecuzione" class="row g-3"><?= $csrf->field() ?><div class="col-md-5"><label class="form-label">Stato<select class="form-select" name="stato"><?= options($stati['intervento_stato_operatore'],$intervento['stato']) ?></select></label></div><div class="col-12"><label class="form-label">Esito e lavoro svolto<textarea class="form-control" name="esito" rows="3" placeholder="Descrivi cosa è stato fatto e il risultato."><?= e($intervento['esito']) ?></textarea></label></div><div class="col-12"><label class="form-label">Note, anomalie o attività da ripetere<textarea class="form-control" name="note_operatore" rows="2"><?= e($intervento['note_operatore']) ?></textarea></label></div><div class="col-12"><button class="btn btn-primary">Salva rapporto</button></div></form><?php endif ?></div></section></div>
<div class="col-lg-5"><section class="card border-0 shadow-sm"><div class="card-body p-4"><h2 class="h5">Foto e documenti</h2><p class="text-secondary small">Carica foto prima/dopo o documenti in PDF. Massimo 10 MB per file.</p><?php if($auth->can('interventi','modifica')): ?><form method="post" enctype="multipart/form-data" action="/app/interventi/<?= (int)$intervento['id'] ?>/allegati" data-file-name-form><?= $csrf->field() ?><label class="form-label" for="attachmentFile">Scegli un file</label><input class="form-control" style="max-width:100%" id="attachmentFile" type="file" name="file" accept="image/jpeg,image/png,image/webp,application/pdf" required><span class="help-text d-block mb-2" data-file-name>Nessun file selezionato</span><button class="btn btn-outline-primary">Carica file</button></form><?php endif ?><?php if(!$allegati): ?><div class="empty-state py-4">Non ci sono ancora allegati.</div><?php else: ?><ul class="list-group list-group-flush mt-3"><?php foreach($allegati as $a): ?><li class="list-group-item px-0 d-flex justify-content-between gap-2"><a class="text-break" href="/app/allegati/<?= (int)$a['id'] ?>"><?= e($a['nome_originale']) ?></a><small class="text-nowrap"><?= number_format((int)$a['dimensione']/1024,0) ?> KB</small></li><?php endforeach ?></ul><?php endif ?></div></section></div></div>
